	/**
	 * Internal helper method to load the root 
	 * 
	 * @param		id	UUID
	 * @return		IoTDevice
	 */
	protected IoTDevice load( UUID id ) throws ProcessingException {
		ioTDevice = IoTDeviceService.getIoTDeviceInstance().getIoTDevice( new IoTDeviceFetchOneSummary(id) );	
		return ioTDevice;
	}


